import random
from collections import Counter
from functools import lru_cache

PRICES = {1: 800, 2: 1520, 3: 2160, 4: 2560, 5: 3000}

# General DP: labeled titles, any non-empty subset may form a group.
# This is the TRUE optimum with no structural restriction.
def general_total(basket):
    c0 = tuple(Counter(basket).get(i, 0) for i in range(1, 6))
    @lru_cache(maxsize=None)
    def dp(c):
        if sum(c) == 0:
            return 0
        best = None
        for mask in range(1, 32):
            size = bin(mask).count("1")
            nc = list(c)
            ok = True
            for i in range(5):
                if mask >> i & 1:
                    if nc[i] == 0:
                        ok = False
                        break
                    nc[i] -= 1
            if not ok:
                continue
            cost = PRICES[size] + dp(tuple(nc))
            if best is None or cost < best:
                best = cost
        return best
    return dp(c0)

# Restricted DP: sorted counts, group = top g books (candidate solution)
def restricted_total(basket):
    c = sorted(Counter(basket).get(i, 0) for i in range(1, 6), reverse=True)
    c = tuple(c) + (0,) * (5 - len(c))
    @lru_cache(maxsize=None)
    def dp(counts):
        if sum(counts) == 0:
            return 0
        distinct = sum(1 for x in counts if x > 0)
        best = None
        for g in range(1, min(5, distinct) + 1):
            nc = list(counts)
            for i in range(g):
                nc[i] -= 1
            nc.sort(reverse=True)
            cost = PRICES[g] + dp(tuple(nc))
            if best is None or cost < best:
                best = cost
        return best
    return dp(c)

random.seed(42)
fails = 0
for trial in range(3000):
    n = random.randint(0, 12)
    basket = [random.randint(1, 5) for _ in range(n)]
    g, r = general_total(basket), restricted_total(basket)
    if g != r:
        fails += 1
        print("MISMATCH", sorted(basket), "general:", g, "restricted:", r)
        if fails > 5:
            break
print("done, mismatches:", fails)
